{
    "name": "weaudit",
    "displayName": "weAudit",
    "description": "Bookmark findings and quickly navigate to areas of interest in the codebase",
    "version": "1.3.1",
    "publisher": "trailofbits",
    "author": "Trail of Bits",
    "categories": [],
    "repository": {
        "type": "git",
        "url": "https://github.com/trailofbits/vscode-weaudit"
    },
    "keywords": [
        "security",
        "audit",
        "code-review"
    ],
    "license": "SEE LICENSE IN LICENSE",
    "galleryBanner": {
        "color": "#ffebdb",
        "theme": "light"
    },
    "icon": "media/icon.png",
    "engines": {
        "vscode": "^1.120.0",
        "node": ">=24"
    },
    "activationEvents": [
        "onStartupFinished",
        "onView:weAudit"
    ],
    "main": "./out/extension.js",
    "contributes": {
        "viewsContainers": {
            "activitybar": [
                {
                    "id": "weAudit",
                    "title": "weAudit",
                    "icon": "media/weAuditLogo.svg"
                }
            ]
        },
        "views": {
            "weAudit": [
                {
                    "id": "codeMarker",
                    "name": "List of Findings",
                    "contextualTitle": "weAudit: "
                },
                {
                    "type": "webview",
                    "id": "findingDetails",
                    "name": "Finding Details",
                    "contextualTitle": "weAudit"
                },
                {
                    "id": "resolvedFindings",
                    "name": "Resolved Findings",
                    "contextualTitle": "weAudit"
                },
                {
                    "type": "webview",
                    "id": "gitConfig",
                    "name": "Repository Configuration",
                    "visibility": "collapsed",
                    "contextualTitle": "weAudit"
                },
                {
                    "id": "savedFindings",
                    "name": "weAudit Files",
                    "contextualTitle": "weAudit"
                }
            ]
        },
        "commands": [
            {
                "command": "weAudit.openGithubIssue",
                "title": "Open Remote Issue",
                "icon": "$(github)"
            },
            {
                "command": "weAudit.openGithubIssueFromDetails",
                "title": "Open Remote Issue",
                "icon": "$(github)"
            },
            {
                "command": "weAudit.copyEntryPermalink",
                "title": "Copy Audit Permalink",
                "icon": "$(link)"
            },
            {
                "command": "weAudit.copyEntryPermalinks",
                "title": "Copy All Audit Permalinks",
                "icon": "$(link)"
            },
            {
                "command": "weAudit.copySelectedCodePermalink",
                "title": "weAudit: Copy Permalink (Audit Repository)"
            },
            {
                "command": "weAudit.copySelectedCodeClientPermalink",
                "title": "weAudit: Copy Permalink (Client Repository)"
            },
            {
                "command": "weAudit.editClientRemote",
                "title": "weAudit: Edit Repository URL (Client)"
            },
            {
                "command": "weAudit.editAuditRemote",
                "title": "weAudit: Edit Repository URL (Audit)"
            },
            {
                "command": "weAudit.editGitHash",
                "title": "weAudit: Edit Git Commit Hash"
            },
            {
                "command": "weAudit.setupRepositoriesCurrent",
                "title": "weAudit: Setup git configurations for this workspace root",
                "icon": "$(github)"
            },
            {
                "command": "weAudit.setupRepositoriesAll",
                "title": "weAudit: Setup git configurations for all workspace roots",
                "icon": "$(github-inverted)"
            },
            {
                "command": "weAudit.nextGitConfig",
                "title": "weAudit: Show next workspace root",
                "icon": "$(arrow-right)"
            },
            {
                "command": "weAudit.prevGitConfig",
                "title": "weAudit: Show previous workspace root",
                "icon": "$(arrow-left)"
            },
            {
                "command": "weAudit.resolveFinding",
                "title": "Resolve Finding",
                "icon": "$(pass)"
            },
            {
                "command": "weAudit.editEntryTitle",
                "title": "Edit Finding Title",
                "icon": "$(edit)"
            },
            {
                "command": "weAudit.editLocationEntry",
                "title": "Edit Location Label",
                "icon": "$(edit)"
            },
            {
                "command": "weAudit.findAndLoadConfigurationFiles",
                "title": "Update Files",
                "icon": "$(refresh)"
            },
            {
                "command": "weAudit.restoreFinding",
                "title": "Restore Finding",
                "icon": "$(check)"
            },
            {
                "command": "weAudit.deleteFinding",
                "title": "Delete Finding",
                "icon": "$(trash)"
            },
            {
                "command": "weAudit.deleteLocation",
                "title": "Delete Location",
                "icon": "$(trash)"
            },
            {
                "command": "weAudit.deleteResolvedFinding",
                "title": "Delete Finding",
                "icon": "$(trash)"
            },
            {
                "command": "weAudit.deleteAllResolvedFinding",
                "title": "Delete All Findings",
                "icon": "$(clear-all)"
            },
            {
                "command": "weAudit.restoreAllResolvedFindings",
                "title": "Restore All Findings",
                "icon": "$(check-all)"
            },
            {
                "command": "weAudit.toggleTreeViewMode",
                "title": "Toggle View Mode",
                "icon": "$(sort-precedence)"
            },
            {
                "command": "weAudit.toggleAudited",
                "title": "weAudit: Mark File as Reviewed"
            },
            {
                "command": "weAudit.addPartiallyAudited",
                "title": "weAudit: Mark Region as Reviewed"
            },
            {
                "command": "weAudit.addFinding",
                "title": "weAudit: New Finding from Selection"
            },
            {
                "command": "weAudit.addNote",
                "title": "weAudit: New Note from Selection"
            },
            {
                "command": "weAudit.editEntryUnderCursor",
                "title": "weAudit: Edit Finding Under Cursor"
            },
            {
                "command": "weAudit.deleteLocationUnderCursor",
                "title": "weAudit: Delete Location Under Cursor"
            },
            {
                "command": "weAudit.showMarkedFilesDayLog",
                "title": "weAudit: Show Daily Log",
                "icon": "$(output)"
            },
            {
                "command": "weAudit.addRegionToAnEntry",
                "title": "weAudit: Add Region to a Finding"
            },
            {
                "command": "weAudit.addRegionToAnEntryWithLabel",
                "title": "weAudit: Add Region to a Finding with Label"
            },
            {
                "command": "weAudit.showFindingsSearchBar",
                "title": "weAudit: Search and Filter Findings"
            },
            {
                "command": "weAudit.exportFindingsInMarkdown",
                "title": "weAudit: Export Findings as Markdown",
                "icon": "$(markdown)"
            },
            {
                "command": "weAudit.navigateToNextPartiallyAuditedRegion",
                "title": "weAudit: Navigate to Next Partially Audited Region"
            },
            {
                "command": "weAudit.toggleFindingsHighlighting",
                "title": "weAudit: Toggle Findings Highlighting"
            },
            {
                "command": "weAudit.editFindingBoundary",
                "title": "weAudit: Edit Finding Boundary"
            },
            {
                "command": "weAudit.stopEditingBoundary",
                "title": "weAudit: Stop Editing Finding Boundary"
            },
            {
                "command": "weAudit.boundaryExpandUp",
                "title": "weAudit: Expand Finding Boundary Up"
            },
            {
                "command": "weAudit.boundaryShrinkTop",
                "title": "weAudit: Shrink Finding Boundary from Top"
            },
            {
                "command": "weAudit.boundaryExpandDown",
                "title": "weAudit: Expand Finding Boundary Down"
            },
            {
                "command": "weAudit.boundaryShrinkBottom",
                "title": "weAudit: Shrink Finding Boundary from Bottom"
            },
            {
                "command": "weAudit.boundaryMoveUp",
                "title": "weAudit: Move Finding Up"
            },
            {
                "command": "weAudit.boundaryMoveDown",
                "title": "weAudit: Move Finding Down"
            },
            {
                "command": "weAudit.editCodeQualityIssueNumber",
                "title": "weAudit: Set Code Quality Issue Number"
            }
        ],
        "keybindings": [
            {
                "command": "weAudit.toggleAudited",
                "key": "ctrl+alt+7",
                "mac": "cmd+7"
            },
            {
                "command": "weAudit.addPartiallyAudited",
                "key": "ctrl+shift+7",
                "mac": "cmd+shift+7"
            },
            {
                "command": "weAudit.addFinding",
                "key": "ctrl+alt+3",
                "mac": "cmd+3"
            },
            {
                "command": "weAudit.addNote",
                "key": "ctrl+alt+4",
                "mac": "cmd+4"
            },
            {
                "command": "weAudit.editEntryUnderCursor",
                "key": "ctrl+alt+6",
                "mac": "cmd+6"
            },
            {
                "command": "weAudit.deleteLocationUnderCursor",
                "key": "ctrl+alt+5",
                "mac": "cmd+5"
            },
            {
                "command": "weAudit.copySelectedCodePermalink",
                "key": "ctrl+alt+8",
                "mac": "cmd+8"
            },
            {
                "command": "weAudit.copySelectedCodeClientPermalink",
                "key": "ctrl+alt+9",
                "mac": "cmd+9"
            },
            {
                "command": "weAudit.navigateToNextPartiallyAuditedRegion",
                "key": "ctrl+alt+0",
                "mac": "cmd+0"
            },
            {
                "command": "weAudit.boundaryExpandUp",
                "key": "ctrl+shift+numpad7",
                "mac": "cmd+shift+numpad7",
                "when": "editorTextFocus"
            },
            {
                "command": "weAudit.boundaryMoveUp",
                "key": "ctrl+shift+numpad8",
                "mac": "cmd+shift+numpad8",
                "when": "editorTextFocus"
            },
            {
                "command": "weAudit.boundaryShrinkTop",
                "key": "ctrl+shift+numpad9",
                "mac": "cmd+shift+numpad9",
                "when": "editorTextFocus"
            },
            {
                "command": "weAudit.boundaryExpandDown",
                "key": "ctrl+shift+numpad1",
                "mac": "cmd+shift+numpad1",
                "when": "editorTextFocus"
            },
            {
                "command": "weAudit.boundaryMoveDown",
                "key": "ctrl+shift+numpad2",
                "mac": "cmd+shift+numpad2",
                "when": "editorTextFocus"
            },
            {
                "command": "weAudit.boundaryShrinkBottom",
                "key": "ctrl+shift+numpad3",
                "mac": "cmd+shift+numpad3",
                "when": "editorTextFocus"
            },
            {
                "command": "weAudit.stopEditingBoundary",
                "key": "ctrl+shift+numpad5",
                "mac": "cmd+shift+numpad5",
                "when": "weAudit.boundaryEditing && editorTextFocus"
            },
            {
                "command": "weAudit.editFindingBoundary",
                "key": "ctrl+shift+numpad5",
                "mac": "cmd+shift+numpad5",
                "when": "!weAudit.boundaryEditing && editorTextFocus"
            }
        ],
        "menus": {
            "commandPalette": [
                {
                    "command": "weAudit.editEntryTitle",
                    "when": "false"
                },
                {
                    "command": "weAudit.editLocationEntry",
                    "when": "false"
                },
                {
                    "command": "weAudit.resolveFinding",
                    "when": "false"
                },
                {
                    "command": "weAudit.openGithubIssue",
                    "when": "false"
                },
                {
                    "command": "weAudit.copyEntryPermalink",
                    "when": "false"
                },
                {
                    "command": "weAudit.findAndLoadConfigurationFiles",
                    "when": "false"
                },
                {
                    "command": "weAudit.restoreFinding",
                    "when": "false"
                },
                {
                    "command": "weAudit.deleteFinding",
                    "when": "false"
                },
                {
                    "command": "weAudit.deleteLocation",
                    "when": "false"
                },
                {
                    "command": "weAudit.deleteResolvedFinding",
                    "when": "false"
                },
                {
                    "command": "weAudit.deleteAllResolvedFinding",
                    "when": "false"
                },
                {
                    "command": "weAudit.boundaryExpandUp",
                    "when": "false"
                },
                {
                    "command": "weAudit.boundaryShrinkTop",
                    "when": "false"
                },
                {
                    "command": "weAudit.boundaryExpandDown",
                    "when": "false"
                },
                {
                    "command": "weAudit.boundaryShrinkBottom",
                    "when": "false"
                },
                {
                    "command": "weAudit.boundaryMoveUp",
                    "when": "false"
                },
                {
                    "command": "weAudit.boundaryMoveDown",
                    "when": "false"
                }
            ],
            "view/title": [
                {
                    "command": "weAudit.findAndLoadConfigurationFiles",
                    "when": "view == savedFindings",
                    "group": "navigation"
                },
                {
                    "command": "weAudit.restoreAllResolvedFindings",
                    "when": "view == resolvedFindings",
                    "group": "navigation@1"
                },
                {
                    "command": "weAudit.deleteAllResolvedFinding",
                    "when": "view == resolvedFindings",
                    "group": "navigation@2"
                },
                {
                    "command": "weAudit.showMarkedFilesDayLog",
                    "when": "view == codeMarker",
                    "group": "navigation@0"
                },
                {
                    "command": "weAudit.exportFindingsInMarkdown",
                    "when": "view == codeMarker",
                    "group": "navigation@1"
                },
                {
                    "command": "weAudit.toggleTreeViewMode",
                    "when": "view == codeMarker",
                    "group": "navigation@2"
                },
                {
                    "command": "weAudit.setupRepositoriesCurrent",
                    "when": "view == gitConfig",
                    "group": "navigation@2"
                },
                {
                    "command": "weAudit.setupRepositoriesAll",
                    "when": "view == gitConfig && workspaceFolderCount > 1",
                    "group": "navigation@3"
                },
                {
                    "command": "weAudit.nextGitConfig",
                    "when": "view == gitConfig",
                    "group": "navigation@1"
                },
                {
                    "command": "weAudit.prevGitConfig",
                    "when": "view == gitConfig",
                    "group": "navigation@0"
                },
                {
                    "command": "weAudit.openGithubIssueFromDetails",
                    "when": "view == findingDetails && weAudit.findingDetailsHasEntry",
                    "group": "navigation"
                }
            ],
            "view/item/context": [
                {
                    "command": "weAudit.editEntryTitle",
                    "when": "view == codeMarker && viewItem != pathOrganizer && viewItem != additionalLocation",
                    "group": "inline@1"
                },
                {
                    "command": "weAudit.copyEntryPermalink",
                    "when": "view == codeMarker && viewItem == additionalLocation",
                    "group": "inline@2"
                },
                {
                    "command": "weAudit.copyEntryPermalinks",
                    "when": "view == codeMarker && viewItem != pathOrganizer && viewItem != additionalLocation",
                    "group": "inline@2"
                },
                {
                    "command": "weAudit.openGithubIssue",
                    "when": "view == codeMarker && viewItem != pathOrganizer && viewItem != additionalLocation",
                    "group": "inline@4"
                },
                {
                    "command": "weAudit.resolveFinding",
                    "when": "view == codeMarker && viewItem != pathOrganizer && viewItem != additionalLocation",
                    "group": "inline@5"
                },
                {
                    "command": "weAudit.deleteFinding",
                    "when": "view == codeMarker && viewItem != pathOrganizer && viewItem != additionalLocation",
                    "group": "inline@6"
                },
                {
                    "command": "weAudit.deleteLocation",
                    "when": "view == codeMarker && viewItem == additionalLocation",
                    "group": "inline@6"
                },
                {
                    "command": "weAudit.editLocationEntry",
                    "when": "view == codeMarker && viewItem == additionalLocation",
                    "group": "inline@1"
                },
                {
                    "command": "weAudit.restoreFinding",
                    "when": "view == resolvedFindings",
                    "group": "inline@1"
                },
                {
                    "command": "weAudit.deleteResolvedFinding",
                    "when": "view == resolvedFindings",
                    "group": "inline@2"
                }
            ],
            "editor/context": [
                {
                    "command": "weAudit.toggleAudited",
                    "group": "1_modification@0"
                },
                {
                    "command": "weAudit.copySelectedCodePermalink",
                    "group": "9_cutcopypaste@0"
                },
                {
                    "command": "weAudit.copySelectedCodeClientPermalink",
                    "group": "9_cutcopypaste@0"
                }
            ]
        },
        "configuration": [
            {
                "title": "General Settings",
                "order": 1,
                "properties": {
                    "weAudit.general.treeViewMode": {
                        "type": "string",
                        "default": "list",
                        "enum": [
                            "list",
                            "byFile"
                        ],
                        "enumDescriptions": [
                            "Group findings in a list",
                            "Group findings by filename"
                        ],
                        "description": "The List of Findings display mode."
                    },
                    "weAudit.general.githubOrganizationName": {
                        "type": "string",
                        "default": "trailofbits",
                        "description": "Defining the organization name for the audit repository enhances the heuristic to determine the correct git remote when creating permalinks."
                    },
                    "weAudit.general.username": {
                        "type": "string",
                        "default": "",
                        "description": "The username to use as the finding's author. (Defaults to the system's username if left empty.)"
                    },
                    "weAudit.general.permalinkSeparator": {
                        "type": "string",
                        "default": "\\n",
                        "description": "The separator to use in permalinks. (Note that \\n is interpreted as a newline)"
                    },
                    "weAudit.general.sortEntriesAlphabetically": {
                        "type": "boolean",
                        "default": false,
                        "description": "Sort findings and notes alphabetically by name in the tree view."
                    },
                    "weAudit.general.skipCodeQualityConfirmation": {
                        "type": "boolean",
                        "default": false,
                        "description": "Skip the confirmation dialog when opening a Code Quality comment. The comment will be copied to clipboard and the issue opened immediately."
                    }
                }
            },
            {
                "title": "Highlight colors",
                "order": 2,
                "properties": {
                    "weAudit.auditedColor": {
                        "type": "string",
                        "default": "#00422355",
                        "description": "Background color for files marked as reviewed (write as #RGB, #RGBA, #RRGGBB or #RRGGBBAA)."
                    },
                    "weAudit.ownFindingColor": {
                        "type": "string",
                        "default": "#ee335555",
                        "description": "Background color for your own findings (write as #RGB, #RGBA, #RRGGBB or #RRGGBBAA)."
                    },
                    "weAudit.otherFindingColor": {
                        "type": "string",
                        "default": "#ee335555",
                        "description": "Background color for other user's findings (write as #RGB, #RGBA, #RRGGBB or #RRGGBBAA)."
                    },
                    "weAudit.ownNoteColor": {
                        "type": "string",
                        "default": "#145ceb55",
                        "description": "Background color for your own notes (write as #RGB, #RGBA, #RRGGBB or #RRGGBBAA)."
                    },
                    "weAudit.otherNoteColor": {
                        "type": "string",
                        "default": "#145ceb55",
                        "description": "Background color for other user's notes (write as #RGB, #RGBA, #RRGGBB or #RRGGBBAA)."
                    }
                }
            }
        ]
    },
    "scripts": {
        "vscode:prepublish": "npm run package",
        "compile": "node ./esbuild.js",
        "package": "node ./esbuild.js --production",
        "watch": "node ./esbuild.js --watch",
        "lint": "eslint --ext ts --color -c .eslintrc.cjs src",
        "test": "npm run test:unit && npm run test:ext",
        "test:all": "npm run test:unit && npm run test:ext && npm run test:ui",
        "test:unit": "mocha -r ts-node/register/transpile-only \"test/unit/**/*.test.ts\" \"test/webview/**/*.test.ts\"",
        "pretest:ext": "npm run compile && tsc -p test/extension/tsconfig.json",
        "test:ext": "vscode-test --config .vscode-test.mjs",
        "pretest:ui": "npm run compile && tsc -p test/ui/tsconfig.json",
        "test:ui": "extest setup-and-run './out/test/ui/**/*.test.js' --code_version max --storage .test-extensions --extensions_dir .test-extensions/extensions --mocha_config test/ui/.mocharc.json -- --disable-extensions",
        "test:ui-setup": "extest setup-tests --code_version max --storage .test-extensions --extensions_dir .test-extensions/extensions",
        "coverage": "npm run coverage:unit",
        "coverage:unit": "nyc npm run test:unit",
        "coverage:ext": "npm run test:ext -- --coverage --coverage-output .nyc_output/extension --coverage-reporter json && nyc report --temp-dir .nyc_output/extension --report-dir coverage/extension",
        "lint:fix": "eslint --ext ts -c .eslintrc.cjs src --fix",
        "format": "biome format --write .",
        "format:check": "biome check --formatter-enabled=true --linter-enabled=false .",
        "typecheck": "tsc --noEmit"
    },
    "devDependencies": {
        "@biomejs/biome": "^2.5.14",
        "@eslint/js": "^10.0.1",
        "@microsoft/eslint-formatter-sarif": "^3.1.0",
        "@stylistic/eslint-plugin": "^5.7.0",
        "@types/asciichart": "^1.5.6",
        "@types/chai": "^5.2.3",
        "@types/glob": "^9.0.0",
        "@types/mocha": "^10.0.10",
        "@types/node": "25.x",
        "@types/sinon": "^22.0.0",
        "@types/vscode": "1.120.0",
        "@types/vscode-webview": "^1.57.1",
        "@typescript-eslint/eslint-plugin": "^8.70.0",
        "@typescript-eslint/parser": "^8.50.0",
        "@vscode/test-cli": "^0.0.15",
        "@vscode/test-electron": "^3.1.0",
        "chai": "^6.2.2",
        "esbuild": "^0.28.2",
        "eslint": "^10.10.0",
        "glob": "^13.0.0",
        "mocha": "^12.0.2",
        "nyc": "^18.0.0",
        "sinon": "^22.1.0",
        "ts-node": "^10.9.2",
        "typescript": "^6.0.3",
        "vscode-extension-tester": "^8.27.0"
    },
    "dependencies": {
        "@vscode/webview-ui-toolkit": "^1.4.0",
        "asciichart": "^1.5.25"
    }
}

{
    "ui": "bdd",
    "timeout": 120000,
    "color": true
}

import * as assert from "node:assert/strict";
import {
    type Entry,
    type FullEntry,
    EntryType,
    createDefaultEntryDetails,
    createLocationEntry,
    createPathOrganizer,
    getEntryIndexFromArray,
    isOldEntry,
} from "../../src/types";

function finding(label = "Finding"): FullEntry {
    return {
        label,
        author: "alice",
        entryType: EntryType.Finding,
        details: createDefaultEntryDetails(),
        locations: [{ path: "file.ts", rootPath: "/workspace", startLine: 2, endLine: 5, label: "Location", description: "Context" }],
    };
}

describe("Entry helpers", () => {
    it("preserves the path label without interpreting special characters", () => {
        assert.deepEqual(createPathOrganizer("src/[test]/file (1).ts"), { pathLabel: "src/[test]/file (1).ts" });
    });

    it("keeps the original location and parent references in a location entry", () => {
        const parent = finding();
        const location = parent.locations[0];
        const entry = createLocationEntry(location, parent);
        assert.equal(entry.parentEntry, parent);
        assert.equal(entry.location, location);
    });

    describe("getEntryIndexFromArray", () => {
        it("finds an equivalent object at a nonzero index", () => {
            assert.equal(getEntryIndexFromArray(finding("Target"), [finding("Other"), finding("Target")]), 1);
        });

        it("returns the first equivalent entry when there are duplicates", () => {
            assert.equal(getEntryIndexFromArray(finding(), [finding("Other"), finding(), finding()]), 1);
        });

        it("returns -1 for missing entries and empty arrays", () => {
            assert.equal(getEntryIndexFromArray(finding("Missing"), [finding()]), -1);
            assert.equal(getEntryIndexFromArray(finding(), []), -1);
        });

        it("ignores edited details and location labels when identifying an entry", () => {
            const edited = finding();
            edited.details.description = "Updated details";
            edited.locations[0].label = "Updated label";
            assert.equal(getEntryIndexFromArray(edited, [finding()]), 0);
        });
    });

    describe("isOldEntry", () => {
        it("recognizes the legacy entry shape used by external commands", () => {
            const entry: Entry = { ...finding(), locations: [{ path: "/workspace/file.ts", startLine: 2, endLine: 5, label: "", description: "" }] };
            assert.equal(isOldEntry(entry), true);
        });

        it("recognizes full findings and preserves the empty-location legacy case", () => {
            assert.equal(isOldEntry(finding()), false);
            assert.equal(isOldEntry({ ...finding(), locations: [] }), true);
        });

        it("accepts a full location entry without trying to index a missing locations array", () => {
            const parent = finding();
            assert.equal(isOldEntry(createLocationEntry(parent.locations[0], parent)), false);
        });
    });
});

import * as assert from "node:assert";
import { countReviewedLines, DayLogEntry, updateFileLog, updateRegionLog } from "../../src/utilities/dayLog";

describe("Daily review log", () => {
    const region = { path: "src/file.ts", startLine: 2, endLine: 5 };

    it("counts inclusive regions without reading or counting the whole file", () => {
        assert.strictEqual(
            countReviewedLines(region, () => assert.fail("Unexpected file read")),
            4,
        );
        assert.strictEqual(
            countReviewedLines({ ...region, endLine: 2 }, () => ""),
            1,
        );
    });

    it("merges overlapping and adjacent selections without double counting", () => {
        let entries = updateRegionLog([], region, true);
        entries = updateRegionLog(entries, { ...region, startLine: 4, endLine: 8 }, true);
        entries = updateRegionLog(entries, { ...region, startLine: 9, endLine: 10 }, true);
        assert.deepStrictEqual(entries, [{ ...region, endLine: 10 }]);
    });

    it("splits and removes unmarked regions without changing the previous snapshot", () => {
        const previous = [region];
        const entries = updateRegionLog(previous, { ...region, startLine: 3, endLine: 4 }, false);
        assert.deepStrictEqual(entries, [
            { ...region, endLine: 2 },
            { ...region, startLine: 5 },
        ]);
        assert.deepStrictEqual(previous, [region]);
        assert.deepStrictEqual(updateRegionLog(entries, region, false), []);
    });

    it("keeps disjoint regions and other files separate", () => {
        const entries = updateRegionLog(["other.ts", region], { ...region, startLine: 10, endLine: 12 }, true);
        assert.strictEqual(entries.length, 3);
        assert.strictEqual(
            entries.reduce((sum, entry) => sum + countReviewedLines(entry, () => "a\nb\n"), 0),
            9,
        );
    });

    it("replaces regions with a whole-file review and removes them when unmarked", () => {
        const entries = updateFileLog([region, "other.ts"], region.path, true);
        assert.deepStrictEqual(entries, ["other.ts", region.path]);
        assert.deepStrictEqual(updateRegionLog(entries, region, true), entries);
        assert.deepStrictEqual(updateFileLog(entries, region.path, false), ["other.ts"]);
        assert.deepStrictEqual(updateFileLog([], region.path, false), []);
    });

    it("loads legacy and mixed logs after JSON persistence", () => {
        const legacy = JSON.parse('[["Mon Sep 21 2026",["src/file.ts"]]]') as [string, DayLogEntry[]][];
        const log = new Map(legacy);
        log.set("Tue Sep 22 2026", updateRegionLog([], region, true));
        const reloaded = new Map(JSON.parse(JSON.stringify([...log])) as [string, DayLogEntry[]][]);
        assert.deepStrictEqual(reloaded.get("Mon Sep 21 2026"), ["src/file.ts"]);
        assert.deepStrictEqual(reloaded.get("Tue Sep 22 2026"), [region]);
    });

    it("preserves whole-file newline counts for CRLF, empty files and final unterminated lines", () => {
        for (const [content, expected] of [
            ["a\r\nb\r\n", 2],
            ["", 0],
            ["a\nb", 1],
        ] as const) {
            assert.strictEqual(
                countReviewedLines("file.ts", () => content),
                expected,
            );
        }
    });
});

import * as assert from "node:assert";
import * as path from "node:path";
import { generatePermalink } from "../../src/utilities/generatePermalink";

describe("generatePermalink", () => {
    const sha = "abc123def456789012345678901234567890abcd";
    const hosts = [
        { remote: "https://github.com/org/repo", route: "blob", fragment: "#L11-L21" },
        { remote: "https://gitlab.com/group/repo", route: "blob", fragment: "#L11-L21" },
        { remote: "https://github.company.com/org/repo", route: "blob", fragment: "#L11-L21" },
        { remote: "https://bitbucket.org/team/repo", route: "src", fragment: "#lines-11:21" },
    ];

    for (const { remote, route, fragment } of hosts) {
        describe(remote, () => {
            const prefix = remote + "/" + route + "/" + sha + "/";

            for (const platform of [path.posix, path.win32]) {
                it("uses URL separators for " + platform.sep + " filesystem paths", () => {
                    const root = platform.resolve("repo");
                    const file = platform.resolve("repo", "src", "nested", "file.ts");
                    const location = Object.freeze({
                        path: platform.relative(root, file),
                        startLine: 10,
                        endLine: 20,
                    });
                    const result = generatePermalink(remote, sha, location, platform.sep);
                    assert.strictEqual(result, prefix + "src/nested/file.ts" + fragment);
                });
            }

            it("handles mixed Windows separators", () => {
                const location = { path: "src\\nested/file.ts", startLine: 10, endLine: 20 };
                const result = generatePermalink(remote, sha, location, "\\");
                assert.strictEqual(result, prefix + "src/nested/file.ts" + fragment);
            });

            it("encodes special characters within each path segment", () => {
                const location = { path: "src/my folder/日本語#?%20&.ts", startLine: 10, endLine: 20 };
                const result = generatePermalink(remote, sha, location);
                const encodedPath = "src/my%20folder/%E6%97%A5%E6%9C%AC%E8%AA%9E%23%3F%2520%26.ts";
                assert.strictEqual(result, prefix + encodedPath + fragment);
                assert.strictEqual(new URL(result).search, "");
                assert.strictEqual(new URL(result).hash, fragment);
            });

            it("encodes Windows path segments after converting separators", () => {
                const location = { path: "src\\my folder\\file#1%.ts", startLine: 10, endLine: 20 };
                const result = generatePermalink(remote, sha, location, "\\");
                assert.strictEqual(result, prefix + "src/my%20folder/file%231%25.ts" + fragment);
            });

            it("preserves a literal backslash in a POSIX filename", () => {
                const location = { path: "src/file\\name.ts", startLine: 10, endLine: 20 };
                const result = generatePermalink(remote, sha, location, "/");
                assert.strictEqual(result, prefix + "src/file%5Cname.ts" + fragment);
            });
        });
    }

    it("defaults to the current OS separator", () => {
        const location = { path: path.join("src", "file.ts"), startLine: 0, endLine: 0 };
        const result = generatePermalink("https://github.com/org/repo", sha, location);
        assert.strictEqual(result, "https://github.com/org/repo/blob/" + sha + "/src/file.ts#L1-L1");
    });

    it("retains the Bitbucket fragment for a single line in a root-level file", () => {
        const location = { path: "file.ts", startLine: 0, endLine: 0 };
        const result = generatePermalink("https://bitbucket.org/team/repo", sha, location);
        assert.strictEqual(result, "https://bitbucket.org/team/repo/src/" + sha + "/file.ts#lines-1:1");
    });
});

